         __u32 reserved;
         __u64 data;
};

/* for KVM_GET_MSRS and KVM_SET_MSRS */
struct kvm_msrs {
         __u32 nmsrs; /* number of msrs in entries */
         __u32 pad;

         __DECLARE_FLEX_ARRAY(struct kvm_msr_entry, entries);
};

